def calc(expr):
    # Tokenizer
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit() or c == '.':
            j = i
            while j < n and (expr[j].isdigit() or expr[j] == '.'):
                j += 1
            # handle numbers like '3.' or '.5'? simple approach
            s = expr[i:j]
            # ensure valid number
            tokens.append(('num', float(s)))
            i = j
            continue
        if c in '+-*/()':
            tokens.append(('op', c))
            i += 1
            continue
        # unknown char
        raise ValueError(f"Unexpected character: {c}")

    # Parser with index
    idx = 0
    def peek():
        if idx < len(tokens):
            return tokens[idx]
        return None

    def consume():
        nonlocal idx
        tok = tokens[idx]
        idx += 1
        return tok

    def parse_expression():
        # Expression: Term ( ( '+' | '-' ) Term )*
        result = parse_term()
        while True:
            tok = peek()
            if tok and tok[0] == 'op' and tok[1] in '+-':
                consume()
                right = parse_term()
                if tok[1] == '+':
                    result = result + right
                else:
                    result = result - right
            else:
                break
        return result

    def parse_term():
        # Term: Factor ( ( '*' | '/' ) Factor )*
        result = parse_factor()
        while True:
            tok = peek()
            if tok and tok[0] == 'op' and tok[1] in '*/':
                consume()
                right = parse_factor()
                if tok[1] == '*':
                    result = result * right
                else:
                    result = result / right
            else:
                break
        return result

    def parse_factor():
        # Factor: '-' Factor | primary
        tok = peek()
        if tok and tok[0] == 'op' and tok[1] == '-':
            consume()
            factor = parse_factor()
            return -factor
        return parse_primary()

    def parse_primary():
        nonlocal idx
        tok = consume()
        if tok[0] == 'num':
            return tok[1]
        if tok[0] == 'op' and tok[1] == '(':
            val = parse_expression()
            # expect ')'
            consume()  # should be ')'
            return val
        # Should not happen
        raise ValueError("Unexpected token")

    # Ensure entire expression consumed
    result = parse_expression()
    if idx != len(tokens):
        raise ValueError("Extra tokens")
    return result

