import bisect

class FenwickTree:
    def __init__(self, size):
        self.n = size
        self.bit = [0] * (size + 1)

    def add(self, idx, delta):
        while idx <= self.n:
            self.bit[idx] += delta
            idx += idx & -idx

    def sum(self, idx):
        res = 0
        while idx > 0:
            res += self.bit[idx]
            idx -= idx & -idx
        return res

    def range_sum(self, left, right):
        if left > right:
            return 0
        return self.sum(right) - self.sum(left - 1)

def count_range_sums(nums: list[int], lower: int, upper: int) -> int:
    n = len(nums)
    if n == 0:
        return 0

    pref = [0] * (n + 1)
    for i, v in enumerate(nums):
        pref[i + 1] = pref[i] + v

    sorted_unique = sorted(set(pref))
    m = len(sorted_unique)
    fenwick = FenwickTree(m)

    ans = 0
    # Add prefix[0] = 0 to Fenwick
    idx0 = bisect.bisect_left(sorted_unique, 0) + 1
    fenwick.add(idx0, 1)

    for j in range(1, n + 1):
        L = pref[j] - upper
        R = pref[j] - lower
        if L > R:
            # No possible i
            # But still add current pref
            pass
        else:
            left_idx = bisect.bisect_left(sorted_unique, L) + 1
            right_idx = bisect.bisect_right(sorted_unique, R)  # exclusive, so Fenwick index is right_idx
            # Fenwick indices are 1-based: right_idx is insertion point for >R, so last index <=R is right_idx
            # Because bisect_right returns index in 0-based sorted_unique, so Fenwick index = right_idx
            if left_idx <= right_idx:
