def integer_root(n: int, k: int) -> int:
    if n == 0:
        return 0
    if k == 1:
        return n

    # Compute a tight upper bound using bit length
    b = n.bit_length()
    m = (b + k - 1) // k  # ceil(b/k)
    high = 1 << m
    if high > n:
        high = n

    low = 0
    while low < high:
        mid = (low + high + 1) // 2
        val = mid ** k
        if val <= n:
            low = mid
        else:
            high = mid - 1
    return low
